(()=>{"use strict";let rows=[],loading=!1;const norm=e=>String(e??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"_").replace(/^_+|_+$/g,"");const bool=e=>["true","1","sim","yes","ativo","on","verdadeiro"].includes(String(e??"").trim().toLowerCase());const num=e=>{const n=parseFloat(String(e??"").trim().replace(",","."));return Number.isFinite(n)?n:0};function parseDateBR(e){const v=String(e??"").trim();if(!v)return null;let m=v.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?$/);if(m){const[,y,mo,d,h,mi,se="00"]=m,x=new Date(`${y}-${String(mo).padStart(2,"0")}-${String(d).padStart(2,"0")}T${String(h).padStart(2,"0")}:${mi}:${se}-03:00`);return Number.isNaN(x.getTime())?null:x}m=v.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})[ T](\d{1,2}):(\d{2})(?::(\d{2}))?$/);if(m){const[,d,mo,y,h,mi,se="00"]=m,x=new Date(`${y}-${String(mo).padStart(2,"0")}-${String(d).padStart(2,"0")}T${String(h).padStart(2,"0")}:${mi}:${se}-03:00`);return Number.isNaN(x.getTime())?null:x}const x=new Date(v);return Number.isNaN(x.getTime())?null:x}function parseTSV(text){const out=[];let row=[],cell="",quoted=!1;const s=String(text??"").replace(/^\uFEFF/,"");for(let i=0;i<s.length;i++){const c=s[i],n=s[i+1];if(c==='"'){if(quoted&&n==='"'){cell+='"';i++}else quoted=!quoted}else if(c==='\t'&&!quoted){row.push(cell);cell=""}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&n==='\n')i++;row.push(cell);cell="";if(row.some(v=>String(v).trim()))out.push(row);row=[]}else cell+=c}row.push(cell);if(row.some(v=>String(v).trim()))out.push(row);return out}function parseSheet(text){const table=parseTSV(text);if(table.length<2)return[];const head=table[0].map(norm);const idx=aliases=>head.findIndex(h=>aliases.map(norm).includes(h));const map={titulo:idx(["torneio","titulo","evento","live"]),canal:idx(["canal","streamer","criador"]),url:idx(["url","link","live_url"]),categoria:idx(["categoria","tipo"]),ativo:idx(["ativo","ao_vivo","aovivo","live"]),data_hora:idx(["data_hora","datahora","data_e_hora","inicio","data"]),duracao:idx(["duracao","duracao_horas","horas"])};return table.slice(1).map((r,i)=>{const get=(k,fallback)=>map[k]>=0?r[map[k]]:r[fallback];return{id:`live-${i}`,titulo:String(get("titulo",0)??"").trim(),canal:String(get("canal",1)??"").trim(),url:String(get("url",2)??"").trim(),categoria:String(get("categoria",3)??"recomendada").trim().toLowerCase()||"recomendada",ativo:bool(get("ativo",4)),data_hora:String(get("data_hora",5)??"").trim(),duracao:num(get("duracao",6))}}).filter(r=>r.titulo.length>2)}function render(){const on=document.getElementById("lives-on-container"),up=document.getElementById("lives-upcoming-container");if(!on||!up)return;on.replaceChildren();up.replaceChildren();const now=new Date(),labels={oficial:"🔴 Oficial",amador:"🟢 Amador",recomendada:"🔵 Recomendada",mobile:"📱 Mobile",emulador:"🖥️ Emulador",emulator:"🖥️ Emulador"};let onCount=0,upCount=0;rows.forEach(r=>{const start=parseDateBR(r.data_hora),end=start&&r.duracao>0?new Date(start.getTime()+r.duracao*36e5):null,inWindow=!!(start&&end&&now>=start&&now<=end),future=!!(start&&now<start);if(!(r.ativo||inWindow||future))return;const a=document.createElement("a");a.className="live-card "+(r.ativo||inWindow?`ativo ${r.categoria}`:"agendado");a.target="_blank";a.rel="noopener noreferrer";if(r.url)a.href=r.url;let badge="";if(r.ativo||inWindow){badge=labels[r.categoria]||"AO VIVO";onCount++}else{const ms=start-now,days=Math.floor(ms/864e5),hours=Math.floor(ms/36e5%24),mins=Math.floor(ms/6e4%60);badge=`⏳ ${days>0?days+"d ":""}${String(hours).padStart(2,"0")}:${String(mins).padStart(2,"0")}`;upCount++}a.innerHTML=`<div class="live-dot"></div><div class="live-card-info"><div class="live-card-titulo"></div><div class="live-card-canal"></div></div><span class="live-card-badge"></span>`;a.querySelector(".live-card-titulo").textContent=r.titulo;a.querySelector(".live-card-canal").textContent=r.canal;a.querySelector(".live-card-badge").textContent=badge;(r.ativo||inWindow?on:up).appendChild(a)});const onEmpty=document.getElementById("lives-on-empty"),upEmpty=document.getElementById("lives-up-empty");if(onEmpty)onEmpty.style.display=onCount?"none":"block";if(upEmpty)upEmpty.style.display=upCount?"none":"block"}async function fetchText(url,timeout=9000){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),timeout);try{const res=await fetch(url,{cache:"default",signal:ctl.signal});if(!res.ok)throw new Error(`HTTP ${res.status}`);return await res.text()}finally{clearTimeout(timer)}}async function load(opts={}){if(loading)return;loading=!0;try{const base=window.CFF_CONFIG?.sheets?.lives;if(!base)throw new Error("Fonte de lives não configurada");const sep=base.includes("?")?"&":"?",url=`${base}${sep}livev=${Math.floor(Date.now()/6e4)}`;let text;try{text=await fetchText(url)}catch(e){await new Promise(r=>setTimeout(r,900));text=await fetchText(url)}const parsed=parseSheet(text);if(parsed.length||!rows.length)rows=parsed;render()}catch(e){if(!opts.silent&&!rows.length){const a=document.getElementById("lives-on-empty"),b=document.getElementById("lives-up-empty");if(a)a.style.display="block";if(b)b.style.display="block"}}finally{loading=!1}}window.loadLives=load;window.updateLivesTick=render;window.buildLivesHTML=render;function boot(){load();if(window.livesInterval)clearInterval(window.livesInterval);if(window.livesRefreshInterval)clearInterval(window.livesRefreshInterval);window.livesInterval=setInterval(render,3e4);window.livesRefreshInterval=setInterval(()=>load({silent:!0}),6e4)}document.readyState==="loading"?document.addEventListener("DOMContentLoaded",boot,{once:!0}):boot()})();
